(function(){'use strict';var last=null;function open(d){last=document.activeElement;document.documentElement.classList.add('vss-open');var b=d.querySelector('.vss-go');if(b)setTimeout(function(){b.focus();},30);}
function close(d){d.remove();if(!document.querySelector('[data-vss]'))document.documentElement.classList.remove('vss-open');if(last&&last.focus)last.focus();}
function wire(d){d.querySelectorAll('[data-vss-close]').forEach(function(a){a.addEventListener('click',function(e){if(a.getAttribute('href')==='#'){e.preventDefault();close(d);}});});d.addEventListener('keydown',function(e){if(e.key==='Escape'&&d.getAttribute('data-vss')==='here')close(d);if(e.key==='Tab'){var f=d.querySelectorAll('a[href], button');if(!f.length)return;var first=f[0],lastEl=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();lastEl.focus();}
else if(!e.shiftKey&&document.activeElement===lastEl){e.preventDefault();first.focus();}}});open(d);}
document.querySelectorAll('[data-vss]').forEach(wire);var tpl=document.getElementById('vss-out-tpl');if(!tpl||!window.fetch)return;var busy=false,done=false,lastPing=Date.now();function el(tag,cls,text){var e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;}
function showOut(k){done=true;var d=el('div','vss');d.setAttribute('data-vss','out');d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-labelledby','vss-title-live');var c=el('div','vss-card');var icon=el('p','vss-icon','👋');icon.setAttribute('aria-hidden','true');c.appendChild(icon);var h=el('h2','vss-title',tpl.getAttribute('data-title'));h.id='vss-title-live';c.appendChild(h);var p=el('p','vss-text'),parts=tpl.getAttribute('data-text').split('%1$s');p.appendChild(document.createTextNode(parts[0]));p.appendChild(el('b','',k.by||''));p.appendChild(document.createTextNode((parts[1]||'').replace('%2$s',k.ago||'')));c.appendChild(p);c.appendChild(el('p','vss-text',tpl.getAttribute('data-text2')));var a=el('div','vss-actions');var go=el('a','btn btn-primary vss-go',tpl.getAttribute('data-go'));go.href=tpl.getAttribute('data-signin');a.appendChild(go);var lk=el('a','vss-link',tpl.getAttribute('data-link'));lk.href=tpl.getAttribute('data-reset');a.appendChild(lk);c.appendChild(a);d.appendChild(c);document.body.appendChild(d);wire(d);}
function ping(){if(busy||done||document.hidden)return;busy=true;lastPing=Date.now();fetch(tpl.getAttribute('data-ping'),{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.ok?r.json():null;}).then(function(j){if(j&&!j.in&&j.kicked)showOut(j.kicked);}).catch(function(){}).then(function(){busy=false;});}
setInterval(ping,90000);function soon(){if(Date.now()-lastPing>15000)ping();}
document.addEventListener('visibilitychange',function(){if(!document.hidden)soon();});window.addEventListener('focus',soon);})();